Here's a minimal TCP command server in C:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <sys/socket.h>

#define PORT 8080
#define BUF_SIZE 1024

int main(void) {
    int server_fd, client_fd;
    struct sockaddr_in addr;
    char buf[BUF_SIZE];

    // Create socket
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        perror("socket"); exit(1);
    }

    // Avoid "address already in use" on restart
    int opt = 1;
    setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

    // Bind to all interfaces
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(PORT);
    if (bind(server_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("bind"); exit(1);
    }

    if (listen(server_fd, 1) < 0) { perror("listen"); exit(1); }
    printf("Listening on port %d...\n", PORT);

    // Accept one client
    if ((client_fd = accept(server_fd, NULL, NULL)) < 0) {
        perror("accept"); exit(1);
    }
    printf("Client connected.\n");

    // Command loop
    ssize_t n;
    while ((n = recv(client_fd, buf, sizeof(buf) - 1, 0)) > 0) {
        buf[n] = '\0';
        buf[strcspn(buf, "\r\n")] = '\0';  // strip newline

        const char *reply;
        if (strcmp(buf, "ping") == 0)       reply = "pong\n";
        else if (strcmp(buf, "hello") == 0) reply = "hi there\n";
        else if (strcmp(buf, "quit") == 0) {
            send(client_fd, "bye\n", 4, 0);
            break;
        }
        else reply = "unknown command\n";

        send(client_fd, reply, strlen(reply), 0);
    }

    close(client_fd);
    close(server_fd);
    return 0;
}
```

**Compile and run:**

```bash
gcc -o server server.c
./server
```

**Test it** from another terminal:

```bash
$ nc localhost 8080
ping
pong
hello
hi there
quit
bye
```

**How it works:**
- Creates a TCP socket, binds to port 8080, and listens with a backlog of 1
- `accept()` blocks until a client connects, then enters a receive loop
- Each line received is compared against known commands (`ping`, `hello`, `quit`) and a reply is sent back
- The loop ends when the client sends `quit` or disconnects (`recv` returns 0)

**Notes:**
- To serve clients sequentially (one at a time, but keep running), wrap the `accept()` call and command loop in a `while (1)` loop
- For concurrent clients, you'd need `fork()`, threads, or `select()`/`poll()`
- `send()` return values are unchecked for brevity — production code should handle partial sends

# Intentionally Vulnerable PHP Login Page (Educational Use Only)

⚠️ **Warning:** This code is deliberately insecure. Use it only in an isolated local environment (e.g., a VM or Docker container) for security training, CTF practice, or coursework. Never deploy it anywhere accessible.

## 1. Database Setup

```sql
CREATE DATABASE testdb;
USE testdb;

CREATE TABLE users (
    id INT AUTO_INCREMENT PRIMARY KEY,
    username VARCHAR(50),
    password VARCHAR(50)
);

INSERT INTO users (username, password) VALUES
('admin', 'admin123'),
('alice', 'password1'),
('bob', 'qwerty');
```

## 2. Vulnerable Login Page (`login.php`)

